import{_ as e,o as t,c as i,ao as r}from"./chunks/framework.CnFgGWne.js";const h=JSON.parse('{"title":"Why Julia for Eye-Tracking?","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/why-julia.md","filePath":"tutorials/why-julia.md","lastUpdated":null}'),o={name:"tutorials/why-julia.md"};function n(s,a,l,c,d,u){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="Why-Julia-for-Eye-Tracking?" tabindex="-1">Why Julia for Eye-Tracking? <a class="header-anchor" href="#Why-Julia-for-Eye-Tracking?" aria-label="Permalink to &quot;Why Julia for Eye-Tracking? {#Why-Julia-for-Eye-Tracking?}&quot;">​</a></h1><h2 id="Performance" tabindex="-1">Performance <a class="header-anchor" href="#Performance" aria-label="Permalink to &quot;Performance {#Performance}&quot;">​</a></h2><p>Julia&#39;s just-in-time (JIT) compilation allows pure-Julia binary readers (such as EyeFun.jl&#39;s <code>.edf</code> and <code>.idf</code> parsers) and sample-level signal processing loops to run at native speed without external C/C++ wrapper libraries.</p><h2 id="Reproducibility" tabindex="-1">Reproducibility <a class="header-anchor" href="#Reproducibility" aria-label="Permalink to &quot;Reproducibility {#Reproducibility}&quot;">​</a></h2><p>Julia&#39;s built-in package manager records exact dependency versions in <code>Project.toml</code> and <code>Manifest.toml</code>, making analysis environments reproducible across machines.</p><h2 id="DataFrames-Integration" tabindex="-1">DataFrames Integration <a class="header-anchor" href="#DataFrames-Integration" aria-label="Permalink to &quot;DataFrames Integration {#DataFrames-Integration}&quot;">​</a></h2><p>EyeFun.jl stores continuous samples and extracted events as standard <code>DataFrames.jl</code> tables, so filtering, grouping, joining, and statistical modeling use standard Julia tabular workflows.</p><h2 id="Interactive-and-Static-Plots" tabindex="-1">Interactive and Static Plots <a class="header-anchor" href="#Interactive-and-Static-Plots" aria-label="Permalink to &quot;Interactive and Static Plots {#Interactive-and-Static-Plots}&quot;">​</a></h2><p><code>Makie.jl</code> supports both interactive data exploration (such as <code>plot_databrowser</code>) and publication-ready static figures including gaze traces, scanpaths, fixation heatmaps, and pupil time courses.</p>',9)])])}const m=e(o,[["render",n]]);export{h as __pageData,m as default};
